@page "/settings"
@rendermode InteractiveServer
@using sv_d43c3759909a41e5ac4062204179f0e4.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h3>Profile Settings</h3>
                @if (profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                <img src="@editDisplayAvatarUrl" alt="Avatar" />
                            </div>
                            <label>Avatar URL</label>
                            <input type="text" @bind="editDisplayAvatarUrl" />
                        </div>
                        <div class="profile-fields">
                            <div class="form-group">
                                <label>Display Name</label>
                                <input type="text" @bind="editDisplayName" />
                            </div>
                            <div class="form-group">
                                <label>Email</label>
                                <input type="email" @bind="editEmail" />
                            </div>
                            <div class="form-group">
                                <label>Bio</label>
                                <textarea rows="4" @bind="editBio"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h3>Notification Preferences</h3>
                @if (notificationPrefs is not null)
                {
                    <div class="toggle-group">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="editEmailNotifications" />
                                <span class="toggle-switch"></span>
                                Email Notifications
                            </label>
                            <span class="toggle-description">Receive notifications via email</span>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="editPushNotifications" />
                                <span class="toggle-switch"></span>
                                Push Notifications
                            </label>
                            <span class="toggle-description">Receive push notifications in browser</span>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="editWeeklyDigest" />
                                <span class="toggle-switch"></span>
                                Weekly Digest
                            </label>
                            <span class="toggle-description">Get a weekly summary of activity</span>
                        </div>
                    </div>

                    <h4>Muted Channels</h4>
                    <div class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@editMutedChannels.Contains(channel)"
                                       @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                <span>#@channel</span>
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h3>Security Settings</h3>
                @if (securitySettings is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label>Current Password</label>
                                    <input type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label>New Password</label>
                                    <input type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label>Confirm Password</label>
                                    <input type="password" @bind="confirmPassword" />
                                </div>
                                <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="security-row">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="editTwoFactorEnabled" />
                                <span class="toggle-switch"></span>
                                Two-Factor Authentication
                            </label>
                            <span class="status-indicator @(editTwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                @(editTwoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </div>
                        @if (securitySettings.LastPasswordChange.HasValue)
                        {
                            <p class="meta-info">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }
                    </div>

                    <h4>Active Sessions</h4>
                    <div class="sessions-table-container">
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == securitySettings.Sessions.First().Id)
                                            {
                                                <span class="current-session-badge">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn-danger-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>

                    @if (showRevokeConfirm && sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h4>Revoke Session</h4>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h3>Appearance Settings</h3>
                @if (appearanceSettings is not null)
                {
                    <div class="appearance-options">
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' /> Light
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' /> Dark
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' /> System
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' /> Small
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' /> Medium
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' /> Large
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Language</label>
                            <select @bind="editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-item">
                            <label class="toggle-label">
                                <input type="checkbox" @bind="editCompactMode" />
                                <span class="toggle-switch"></span>
                                Compact Mode
                            </label>
                            <span class="toggle-description">Reduce spacing and padding throughout the UI</span>
                        </div>
                    </div>

                    <h4>Live Preview</h4>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">
                            <strong>Preview Panel</strong>
                        </div>
                        <div class="preview-body">
                            <p>This is how your content will look with the selected settings.</p>
                            <p>Theme: <strong>@editTheme</strong> | Font: <strong>@editFontSize</strong> | Language: <strong>@editLanguage</strong></p>
                            <button class="preview-button">Sample Button</button>
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    // Toast
    private string toastMessage = "";
    private string toastType = "";

    // Profile
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editDisplayAvatarUrl = "";

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private List<string> allChannels = new() { "general", "announcements", "random", "dev-team", "design" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool editTwoFactorEnabled;
    private bool showRevokeConfirm;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearanceSettings;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section)
    {
        activeSection = section;
        DismissToast();
    }

    // Profile methods
    private async Task LoadProfile()
    {
        profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editBio = profile.Bio;
        editDisplayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        if (notificationPrefs is null) return;
        editEmailNotifications = notificationPrefs.EmailNotifications;
        editPushNotifications = notificationPrefs.PushNotifications;
        editWeeklyDigest = notificationPrefs.WeeklyDigest;
        editMutedChannels = new List<string>(notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!isMuted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        if (securitySettings is not null)
            editTwoFactorEnabled = securitySettings.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirm = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        showRevokeConfirm = false;
        sessionToRevoke = null;
        await LoadSecurity();
        ShowToast("Session revoked.", "success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        appearanceSettings = await SettingsService.GetAppearanceAsync();
        if (appearanceSettings is null) return;
        editTheme = appearanceSettings.Theme;
        editFontSize = appearanceSettings.FontSize;
        editLanguage = appearanceSettings.Language;
