    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!isMuted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        if (securitySettings is not null)
            editTwoFactorEnabled = securitySettings.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirm = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        showRevokeConfirm = false;
        sessionToRevoke = null;
        await LoadSecurity();
        ShowToast("Session revoked.", "success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        appearanceSettings = await SettingsService.GetAppearanceAsync();
        if (appearanceSettings is null) return;
        editTheme = appearanceSettings.Theme;
        editFontSize = appearanceSettings.FontSize;
        editLanguage = appearanceSettings.Language;
        editCompactMode = appearanceSettings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editTheme.ToLower()} preview-font-{editFontSize.ToLower()}";
        if (editCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helpers
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
    }

    private void DismissToast()
    {
        toastMessage = "";
        toastType = "";
    }
}

